def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if any two numbers in the given list are closer to each other than the specified threshold.

    Parameters:
    numbers (List[float]): A list of numeric values.
    threshold (float): The distance threshold to compare against.

    Returns:
    bool: True if any pair of numbers is closer than threshold, False otherwise.

    Raises:
    TypeError: If 'numbers' is not a list, if 'threshold' is not a number,
               or if any element in 'numbers' is not numeric.
    """
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a number")
    for n in numbers:
        if not isinstance(n, (int, float)):
            raise TypeError("all elements in numbers must be numeric")

    if len(numbers) < 2:
        return False

    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if abs(sorted_nums[i + 1] - sorted_nums[i]) < threshold:
            return True
    return False

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    # Build grid of values (1-indexed)
    values = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            values[x][y] = v

    if N == 1:
        return values[1][1]

    INF_NEG = -10**15
    # dp[i1][i2] = max sum when first path at (i1, k-i1), second at (i2, k-i2)
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = values[1][1]

    for k in range(3, 2 * N + 1):
        new_dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = INF_NEG
                # consider previous positions (di1, di2) where di = 0 means came from left, 1 means from up
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        prev = dp[pi1][pi2]
                        if prev > best:
                            best = prev
                if best == INF_NEG:
                    continue
                add = values[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += values[i2][j2]
                new_dp[i1][i2] = best + add
        dp = new_dp

    return dp[N][N]

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string must consist only of decimal digits.
    If K is greater than N-1, the function returns 0. If the input is invalid, a ValueError
    is raised.
    """
    # Input validation
    if not isinstance(num_str, str) or not num_str.isdigit():
        raise ValueError("num_str must be a string of digits")
    if not isinstance(N, int) or not isinstance(K, int):
        raise ValueError("N and K must be integers")
    if N != len(num_str):
        raise ValueError("N does not match the length of num_str")
    if K < 0:
        raise ValueError("K must be non-negative")
    if K > N - 1:
        return 0

    # Precompute integer values for all substrings
    sub_int = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            sub_int[i][j] = val

    # DP table: dp[i][k] = max product for prefix of length i with k multiplications
    dp = [[-1] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplications
    for i in range(1, N + 1):
        dp[i][0] = sub_int[0][i]

    # Fill DP table
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # need at least k+1 digits to place k multiplications
            best = -1
            for j in range(k, i):
                if dp[j][k - 1] != -1:
                    prod = dp[j][k - 1] * sub_int[j][i]
                    if prod > best:
                        best = prod
            dp[i][k] = best

    return dp[N][K] if dp[N][K] != -1 else 0

